#include "wdt.hpp"
#include <tlm_utils/simple_initiator_socket.h>
#include <iostream>
#include <sstream>
#include <vector>
#include <stdexcept>

using namespace sc_core;

// Text is a private, versioned adapter wire format generated by the CLI.
// Scheduling and dependency feedback remain inside the simulator process.
struct operation {
    unsigned command, relative;
    std::uint64_t at, address, value, delay;
    unsigned length, width, byte_enable;
};
struct reset_change { std::uint64_t at; bool level; };

class scenario_driver : public sc_module {
public:
    tlm_utils::simple_initiator_socket<scenario_driver> socket{"socket"};
    sc_out<bool> reset_n{"reset_n"};
    bool done = false;
    std::vector<operation> operations;
    std::vector<reset_change> resets;
    std::uint64_t end;
    std::ofstream responses;
    SC_HAS_PROCESS(scenario_driver);
    scenario_driver(sc_module_name name, const std::string& response_path)
        : sc_module(name), responses(response_path) {
        if (!responses) throw std::runtime_error("Cannot open responses");
        responses << "transaction_id,tick,status,value\n";
        SC_THREAD(drive);
        SC_THREAD(reset_driver);
    }
    void reset_driver() {
        for (const auto& change : resets) {
            wait(sc_time::from_value(change.at) - sc_time_stamp());
            reset_n.write(change.level);
        }
    }
    void drive() {
        for (std::size_t i = 0; i < operations.size(); ++i) {
            const auto& op = operations[i];
            const auto target = op.relative ? sc_time_stamp() + sc_time::from_value(op.at)
                                            : sc_time::from_value(op.at);
            if (target < sc_time_stamp()) throw std::runtime_error("Overlapping absolute offers");
            wait(target - sc_time_stamp());
            if (sc_time_stamp().value() >= end) break;
            unsigned char data[4], enables[4] = {255, 255, 255, 255};
            for (unsigned j = 0; j < 4; ++j) data[j] = static_cast<unsigned char>(op.value >> (8*j));
            tlm::tlm_generic_payload payload;
            payload.set_command(static_cast<tlm::tlm_command>(op.command));
            payload.set_address(op.address);
            payload.set_data_ptr(data);
            payload.set_data_length(op.length);
            payload.set_streaming_width(op.width);
            if (op.byte_enable) { payload.set_byte_enable_ptr(enables); payload.set_byte_enable_length(4); }
            auto delay = sc_time::from_value(op.delay);
            socket->b_transport(payload, delay);
            if (delay != SC_ZERO_TIME || payload.is_dmi_allowed())
                throw std::runtime_error("Adapter timing/DMI contract violated");
            std::uint32_t value = 0;
            for (unsigned j = 0; j < 4; ++j) value |= std::uint32_t(data[j]) << (8*j);
            responses << i+1 << ',' << sc_time_stamp().value() << ','
                      << static_cast<int>(payload.get_response_status()) << ',' << value << '\n';
            if (!responses) throw std::runtime_error("Response write failed");
        }
        done = true;
    }
};

int sc_main(int argc, char** argv) {
    try {
        if (argc != 6) throw std::runtime_error("Usage: wdt_scenario workload trace responses metadata max_events");
        sc_set_time_resolution(1, SC_NS);
        std::ifstream input(argv[1]);
        std::string magic;
        std::uint64_t period, first, latency, end, drain;
        if (!(input >> magic >> period >> first >> latency >> end >> drain) || magic != "WDT1")
            throw std::runtime_error("Invalid workload header");
        if (!period || !first || !drain || end > drain) throw std::runtime_error("Invalid timing");
        tlm_lab::trace_sink trace(argv[2], std::stoull(argv[5]));
        scenario_driver driver("driver", argv[3]);
        driver.end = end;
        std::string kind;
        while (input >> kind) {
            if (kind == "reset") {
                reset_change r{};
                if (!(input >> r.at >> r.level)) throw std::runtime_error("Invalid reset");
                driver.resets.push_back(r);
            } else if (kind == "op") {
                operation op{};
                if (!(input >> op.command >> op.relative >> op.at >> op.address >> op.value
                            >> op.delay >> op.length >> op.width >> op.byte_enable))
                    throw std::runtime_error("Invalid operation");
                driver.operations.push_back(op);
            } else throw std::runtime_error("Unknown workload record");
        }
        sc_clock clock("clock", sc_time::from_value(period), 0.5, sc_time::from_value(first), true);
        sc_signal<bool> reset_n("reset_n"), irq("irq"), reset_request("reset_request");
        tlm_lab::wdt dut("wdt", sc_time::from_value(latency), trace);
        dut.clk(clock); dut.reset_n(reset_n); dut.irq(irq); dut.reset_request(reset_request);
        driver.socket.bind(dut.regs); driver.reset_n(reset_n);
        // Include all delta activity at the inclusive drain edge.
        sc_start(sc_time::from_value(drain + 1));
        trace.finish();
        driver.responses.flush();
        if (!driver.responses) throw std::runtime_error("Response flush failed");
        std::ofstream metadata(argv[4]);
        metadata << "{\"systemc_version\":\"" << sc_version()
                 << "\",\"resolution_ns\":1,\"event_count\":" << trace.count()
                 << ",\"event_digest\":\"" << trace.fingerprint()
                 << "\",\"finished\":" << (driver.done ? "true" : "false") << "}\n";
        metadata.flush();
        if (!metadata) throw std::runtime_error("Metadata write failed");
        return driver.done ? 0 : 3;
    } catch (const std::exception& error) {
        std::cerr << "FAIL: " << error.what() << '\n';
        return 1;
    }
}
